import React, {useEffect, useRef, useState} from 'react';
import {AbsoluteFill, Video, staticFile, continueRender, delayRender} from 'remotion';

export const Probe0: React.FC = () => {
  const ref = useRef<HTMLVideoElement>(null);
  const [info, setInfo] = useState('pending');
  const handle = delayRender('probe0');
  useEffect(() => {
    const v = ref.current;
    if (!v) return;
    let n = 0;
    const t = setInterval(() => {
      n++;
      const c = document.createElement('canvas');
      c.width = 64; c.height = 64;
      const ctx = c.getContext('2d')!;
      ctx.drawImage(v, 0, 0, 64, 64);
      const d = ctx.getImageData(0, 0, 64, 64).data;
      let black = 0, other = 0;
      for (let i = 0; i < d.length; i += 4) {
        (d[i] < 10 && d[i+1] < 10 && d[i+2] < 10) ? black++ : other++;
      }
      const s = `n=${n} rs=${v.readyState} seek=${v.seeking} t=${v.currentTime.toFixed(3)} w=${v.videoWidth} black=${black} other=${other}`;
      setInfo(s);
      console.log('PROBE0', s);
      if (n >= 12) { clearInterval(t); continueRender(handle); }
    }, 200);
    return () => clearInterval(t);
  }, []);
