      if (done) return;
      done = true;
      try {
        const c = document.createElement('canvas');
        c.width = 64; c.height = 64;
        const ctx = c.getContext('2d')!;
        ctx.drawImage(v, 0, 0, 64, 64);
        const d = ctx.getImageData(0, 0, 64, 64).data;
        let black = 0, other = 0;
        for (let i = 0; i < d.length; i += 4) {
          (d[i] < 10 && d[i+1] < 10 && d[i+2] < 10) ? black++ : other++;
        }
        setInfo(`${label} rs=${v.readyState} seek=${v.seeking} t=${v.currentTime.toFixed(4)} w=${v.videoWidth} black=${black} other=${other} q=${v.getVideoPlaybackQuality ? v.getVideoPlaybackQuality().totalVideoFrames : -1}`);
